import { useId } from "react";
import styles from "./sorting-options.module.less";
import { multipleClassNames } from "@/core/helpers";

export type SortingOption<ValueType extends string> = {
  value: ValueType;
  label: string;
};

export type SortingOptionsProps<ValueType extends string> = {
  /** Heading shown above the options, also used as the radio group's accessible name. */
  heading?: string;
  options: Array<SortingOption<ValueType>>;
  /** Controlled selection. Update this from `onChange`. */
  value: ValueType;
  onChange: (value: ValueType) => void;
  className?: string;
};

export const SortingOptions = <ValueType extends string>({
  heading,
  options,
  value,
  onChange,
  className,
}: SortingOptionsProps<ValueType>) => {
  // Unique per instance so several lists on one page don't share a radio group.
  const name = useId();

  return (
    <fieldset className={multipleClassNames(styles.fieldset, className)}>
      {heading && <legend className={multipleClassNames(styles.heading, "heading-xs")}>{heading}</legend>}
      <div className={styles.options}>
        {options.map((option) => {
          const id = `${name}-${option.value}`;
          const isSelected = option.value === value;
          return (
            <div key={option.value} className={styles.option}>
              <input
                className={styles.input}
                type="radio"
                id={id}
                name={name}
                value={option.value}
                checked={isSelected}
                onChange={() => onChange(option.value)}
              />
              <label className={multipleClassNames(styles.label, "body-m")} htmlFor={id}>
                <span className={styles.icon} aria-hidden="true" />
                {option.label}
              </label>
            </div>
          );
        })}
      </div>
    </fieldset>
  );
};
