import { Meta, StoryObj } from "@storybook/react";
import { ComponentProps, useState } from "react";
import { action } from "storybook/actions";
import { expect, userEvent, within } from "storybook/test";
import { SortingOptions } from "./sorting-options";

const InteractiveSortingOptions = (props: ComponentProps<typeof SortingOptions<string>>) => {
  const [value, setValue] = useState(props.value);
  return (
    <SortingOptions
      {...props}
      value={value}
      onChange={(next) => {
        setValue(next);
        action("onChange")(next);
      }}
    />
  );
};

const meta = {
  title: "Primitives/Sorting Options",
  component: SortingOptions<string>,
  parameters: {
    docs: {
      description: {
        component:
          "Radio group for picking how a list is sorted. All options are always visible and wrap on small " +
          "screens. Colors come from the `--component-sorting-options-*` tokens, so page themes apply.",
      },
    },
  },
  render: (args) => <InteractiveSortingOptions {...args} />,
  args: {
    heading: "Sortering",
    value: "popularity",
    onChange: () => {},
    options: [
      { value: "alphabetical", label: "Namn (A-Ö)" },
      { value: "popularity", label: "Popularitet" },
      { value: "waitTime", label: "Väntetid" },
      { value: "queueTime", label: "Kötid" },
    ],
  },
} satisfies Meta<typeof SortingOptions<string>>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByLabelText("Namn (A-Ö)"));
    await expect(canvas.getByLabelText("Namn (A-Ö)")).toBeChecked();
  },
};

export const TwoOptions: Story = {
  args: {
    options: [
      { value: "alphabetical", label: "Namn (A-Ö)" },
      { value: "popularity", label: "Popularitet" },
    ],
  },
};
